
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  ArrowLeft, Save, Plus, Trash2, GripVertical, 
  Video, Clock, FileText, CheckCircle2, Layout, Layers, Info, X
} from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { useAuth } from '../context/AuthContext';
import { CourseModule, CourseLesson, ShopProduct } from '../types';

type EditorTab = 'details' | 'curriculum' | 'settings';

const CourseEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  // Fixed: methods addItem and updateItem instead of addStoreItem and updateStoreItem
  const { addItem, updateItem, getStoreItem } = useShop();
  const { user } = useAuth();
  
  const [activeTab, setActiveTab] = useState<EditorTab>('details');
  const [formData, setFormData] = useState<Partial<ShopProduct>>({
    title: '',
    price: 0,
    originalPrice: 0,
    description: '',
    image: '',
    tags: [],
    features: [],
    type: 'course',
    content: []
  });

  const [modules, setModules] = useState<CourseModule[]>([]);

  useEffect(() => {
    if (id) {
      const item = getStoreItem(id);
      if (item && item.type === 'course') {
        setFormData(item);
        setModules(item.content || []);
      }
    }
  }, [id, getStoreItem]);

  // Fixed: added async to handle asynchronous addItem/updateItem calls
  const handleSave = async () => {
    const finalData: ShopProduct = {
      id: id || `c_${Date.now()}`,
      authorId: formData.authorId || user?._id,
      title: formData.title || 'Untitled Course',
      price: Number(formData.price),
      originalPrice: formData.originalPrice ? Number(formData.originalPrice) : undefined,
      type: 'course',
      image: formData.image || 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&q=80&w=1000',
      rating: formData.rating || 0,
      reviews: formData.reviews || 0,
      tags: typeof formData.tags === 'string' ? (formData.tags as string).split(',').map((s: string) => s.trim()) : (formData.tags || []),
      description: formData.description || '',
      features: typeof formData.features === 'string' ? (formData.features as string).split('\n').filter(Boolean) : (formData.features || []),
      content: modules
    };

    if (id) {
      // Fixed: updated method name and added type parameter
      await updateItem('course', id, finalData);
    } else {
      // Fixed: updated method name and added type parameter
      await addItem('course', finalData);
    }
    navigate('/dashboard');
  };

  const addModule = () => {
    setModules([...modules, { id: `m_${Date.now()}`, title: 'New Module', lessons: [] }]);
  };

  const updateModule = (moduleId: string, title: string) => {
    setModules(modules.map(m => m.id === moduleId ? { ...m, title } : m));
  };

  const deleteModule = (moduleId: string) => {
    setModules(modules.filter(m => m.id !== moduleId));
  };

  const addLesson = (moduleId: string) => {
    setModules(modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, { id: `l_${Date.now()}`, title: 'New Lesson', duration: '0:00', isCompleted: false }] } : m));
  };

  const updateLesson = (moduleId: string, lessonId: string, field: keyof CourseLesson, value: any) => {
    setModules(modules.map(m => m.id === moduleId ? { ...m, lessons: m.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l) } : m));
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    setModules(modules.map(m => m.id === moduleId ? { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) } : m));
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-20 pt-16">
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 sticky top-16 z-40">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate('/dashboard')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-500">
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white truncate max-w-[150px] sm:max-w-none">
              {id ? 'Edit Course' : 'Create Course'}
            </h1>
          </div>
          <button 
            onClick={handleSave}
            className="px-4 py-1.5 md:px-6 md:py-2 bg-emerald-600 text-white rounded-lg font-bold text-sm md:text-base hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20 flex items-center gap-2"
          >
            <Save size={18} /> <span className="hidden sm:inline">Save Course</span><span className="sm:hidden">Save</span>
          </button>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 py-8 flex flex-col lg:flex-row gap-8">
        {/* Sidebar Navigation - Horizontal Scroll on Mobile */}
        <aside className="lg:w-64 shrink-0">
          <div className="flex lg:flex-col overflow-x-auto lg:overflow-x-visible pb-2 lg:pb-0 gap-2 scrollbar-hide">
            {[
              { id: 'details', label: 'Details', icon: Info },
              { id: 'curriculum', label: 'Curriculum', icon: Layers },
              { id: 'settings', label: 'Settings', icon: Layout }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as EditorTab)}
                className={`flex items-center gap-2 md:gap-3 px-4 py-2.5 md:py-3 rounded-xl font-bold text-sm transition-all whitespace-nowrap border ${
                  activeTab === tab.id 
                  ? 'bg-emerald-600 text-white border-emerald-500 shadow-md' 
                  : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </div>
        </aside>

        {/* Main Content */}
        <div className="flex-1 min-w-0">
          <AnimatePresence mode="wait">
            {activeTab === 'details' && (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="space-y-6">
                <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-6">
                  <div>
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Course Title</label>
                    <input 
                      type="text" 
                      value={formData.title} 
                      onChange={e => setFormData({...formData, title: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors text-lg font-bold dark:text-white"
                      placeholder="e.g. Master MQL5 Programming"
                    />
                  </div>
                  
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Price ($)</label>
                      <input 
                        type="number" 
                        value={formData.price} 
                        onChange={e => setFormData({...formData, price: Number(e.target.value)})}
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"
                      />
                    </div>
                    <div>
                        <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Original Price ($)</label>
                        <input 
                            type="number" 
                            value={formData.originalPrice || ''} 
                            onChange={e => setFormData({...formData, originalPrice: Number(e.target.value)})}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"
                            placeholder="Optional"
                        />
                    </div>
                  </div>
                  
                  <div>
                      <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Cover Image URL</label>
                      <input 
                        type="text" 
                        value={formData.image} 
                        onChange={e => setFormData({...formData, image: e.target.value})}
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"
                        placeholder="https://..."
                      />
                  </div>

                  <div>
                    <label className="block text-xs font-black uppercase text-slate-500 mb-2 tracking-widest">Description</label>
                    <textarea 
                      rows={5}
                      value={formData.description}
                      onChange={e => setFormData({...formData, description: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"
                    />
                  </div>
                </div>
              </motion.div>
            )}

            {activeTab === 'curriculum' && (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="space-y-6">
                <div className="flex justify-between items-center px-2">
                   <h2 className="text-xl font-bold text-slate-900 dark:text-white">Curriculum Builder</h2>
                   <button onClick={addModule} className="px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-lg font-bold text-sm hover:opacity-90 flex items-center gap-2">
                     <Plus size={16} /> Add Module
                   </button>
                </div>
                <div className="space-y-4">
                  {modules.map((module, mIdx) => (
                    <div key={module.id} className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                      <div className="bg-slate-50 dark:bg-slate-800/50 p-4 flex items-center gap-3 border-b border-slate-200 dark:border-slate-800">
                        <GripVertical size={20} className="text-slate-400 cursor-grab hidden md:block" />
                        <input type="text" value={module.title} onChange={(e) => updateModule(module.id, e.target.value)} className="bg-transparent border-none outline-none font-bold text-slate-900 dark:text-white flex-1 focus:ring-0" />
                        <button onClick={() => deleteModule(module.id)} className="text-slate-400 hover:text-red-500 p-2"><Trash2 size={18} /></button>
                      </div>
                      <div className="p-4 space-y-3">
                        {module.lessons.map((lesson, lIdx) => (
                          <div key={lesson.id} className="flex flex-col md:flex-row md:items-center gap-3 bg-slate-50/50 dark:bg-slate-950/30 p-3 rounded-xl border border-slate-100 dark:border-slate-800">
                             <div className="flex-1 flex items-center gap-3">
                                <span className="text-xs font-black text-slate-400">{lIdx + 1}</span>
                                <input type="text" value={lesson.title} onChange={(e) => updateLesson(module.id, lesson.id, 'title', e.target.value)} className="bg-transparent outline-none font-medium text-slate-900 dark:text-white flex-1 text-sm" placeholder="Lesson Title"/>
                             </div>
                             <div className="flex items-center gap-2">
                                <div className="relative flex-1 md:w-24">
                                    <Clock size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"/>
                                    <input type="text" value={lesson.duration} onChange={(e) => updateLesson(module.id, lesson.id, 'duration', e.target.value)} className="w-full bg-white dark:bg-slate-900 pl-8 pr-2 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 outline-none text-xs" placeholder="00:00"/>
                                </div>
                                <button onClick={() => deleteLesson(module.id, lesson.id)} className="p-1.5 text-slate-300 hover:text-red-500"><X size={16} /></button>
                             </div>
                          </div>
                        ))}
                        <button onClick={() => addLesson(module.id)} className="w-full py-2 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-xl text-xs font-bold text-emerald-600 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-900/10 flex items-center justify-center gap-1"><Plus size={14} /> Add Lesson</button>
                      </div>
                    </div>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
};

export default CourseEditor;
